// Android application module for h4rn (generated by `tauri android init`).
//
// This file is checked in under `native/android/app/` and copied over the
// generated project by `scripts/mobile-android.sh` so the release signing
// configuration survives every regeneration. Keep it in sync with the Tauri CLI
// 2.12.x template; the h4rn additions are the Google Services switch, the
// `signingConfigs` block, the unit-test settings and the extra dependencies.
import java.util.Properties
import org.gradle.api.tasks.testing.logging.TestExceptionFormat
import org.jetbrains.kotlin.gradle.dsl.JvmTarget

// Firebase Messaging compiles into every build, but the Google Services plugin
// (and therefore a real Firebase project) is applied only when the operator
// supplies `H4RN_ANDROID_GOOGLE_SERVICES_FILE`. Without it the app still
// builds and Settings reports that alerts are unavailable (ADR-051).
buildscript {
    repositories {
        google()
        mavenCentral()
    }
    dependencies {
        classpath("com.google.gms:google-services:4.4.4")
    }
}

plugins {
    id("com.android.application")
    id("org.jetbrains.kotlin.android")
    id("rust")
}

val googleServicesFile = System.getenv("H4RN_ANDROID_GOOGLE_SERVICES_FILE")
    ?.takeIf { it.isNotBlank() }
    ?.let { file(it) }
val hasGoogleServices = googleServicesFile != null && googleServicesFile.exists()
if (hasGoogleServices) {
    apply(plugin = "com.google.gms.google-services")
}

val tauriProperties = Properties().apply {
    val propFile = file("tauri.properties")
    if (propFile.exists()) {
        propFile.inputStream().use { load(it) }
    }
}

// Release signing comes from CI secrets, never from the tree. When any value is
// absent the release variant falls back to the debug signing key so local and
// unsigned CI builds still produce an installable artifact.
val releaseKeystorePath = System.getenv("ANDROID_KEYSTORE_PATH")?.takeIf { it.isNotBlank() }
val releaseKeystorePassword = System.getenv("ANDROID_KEYSTORE_PASSWORD")
val releaseKeyAlias = System.getenv("ANDROID_KEY_ALIAS")
val releaseKeyPassword = System.getenv("ANDROID_KEY_PASSWORD")
val releaseKeystoreFile = releaseKeystorePath?.let { file(it) }
val hasReleaseSigning =
    releaseKeystoreFile != null &&
        releaseKeystoreFile.exists() &&
        !releaseKeystorePassword.isNullOrBlank() &&
        !releaseKeyAlias.isNullOrBlank()

android {
    compileSdk = 37
    namespace = "dev.h4rn.app"
    defaultConfig {
        // The transport is Noise end-to-end encrypted over a pinned daemon key,
        // so release builds permit cleartext candidates too; see
        // src/main/res/xml/network_security_config.xml and docs/mobile.md.
        manifestPlaceholders["usesCleartextTraffic"] = "true"
        applicationId = "dev.h4rn.app"
        minSdk = 26
        targetSdk = 37
        versionCode = tauriProperties.getProperty("tauri.android.versionCode", "1").toInt()
        versionName = tauriProperties.getProperty("tauri.android.versionName", "1.1.0")
    }
    signingConfigs {
        if (hasReleaseSigning) {
            create("release") {
                storeFile = releaseKeystoreFile
                storePassword = releaseKeystorePassword
                keyAlias = releaseKeyAlias
                keyPassword = releaseKeyPassword ?: releaseKeystorePassword
            }
        }
    }
    buildTypes {
        getByName("debug") {
            manifestPlaceholders["usesCleartextTraffic"] = "true"
            isDebuggable = true
            isJniDebuggable = true
            isMinifyEnabled = false
            packaging {
                jniLibs.keepDebugSymbols.add("*/arm64-v8a/*.so")
                jniLibs.keepDebugSymbols.add("*/armeabi-v7a/*.so")
                jniLibs.keepDebugSymbols.add("*/x86/*.so")
                jniLibs.keepDebugSymbols.add("*/x86_64/*.so")
            }
        }
        getByName("release") {
            // Unsigned/dev builds use the debug key; a CI job with the keystore
            // secrets replaces it with the upload key (see docs/release.md).
            signingConfig =
                if (hasReleaseSigning) {
                    signingConfigs.getByName("release")
                } else {
                    signingConfigs.getByName("debug")
                }
            optimization {
               enable = true
            }
            proguardFiles(
                *fileTree(".") {
                  include("**/*.pro")
                  exclude("build/**")
                }.files.toTypedArray()
            )
        }
    }
    compileOptions {
        sourceCompatibility = JavaVersion.VERSION_1_8
        targetCompatibility = JavaVersion.VERSION_1_8
    }
    buildFeatures {
        buildConfig = true
    }
}

kotlin {
    compilerOptions {
        jvmTarget = JvmTarget.JVM_1_8
    }
}

rust {
    rootDirRel = "../../../"
}

// PushResourcesTest reads every language's push_strings.xml straight from
// src/main/res. Declare that folder as a test input so editing a translation
// reruns the tests instead of leaving them up to date. A failure prints its
// assertion message (which language and which string), so the CI log says
// what broke without downloading the report.
tasks.withType<Test>().configureEach {
    inputs.dir("src/main/res")
        .withPropertyName("pushResources")
        .withPathSensitivity(PathSensitivity.RELATIVE)
    // Every test is listed, so a green CI log shows the tests really ran;
    // a failure also prints its assertion message.
    testLogging {
        events("passed", "skipped", "failed")
        exceptionFormat = TestExceptionFormat.FULL
    }
}

dependencies {
    // Present in every build so the Kotlin compiles without a Firebase
    // project; without google-services.json nothing initialises at runtime.
    implementation("com.google.firebase:firebase-messaging:24.1.1")
    // 1.18 is the first core release with NotificationCompat's Android 16
    // Live Update wrappers (`setRequestPromotedOngoing`, `ProgressStyle`),
    // which ADR-053 uses behind an API check so older releases stay plain.
    implementation("androidx.core:core-ktx:1.18.0")
    implementation("androidx.webkit:webkit:1.14.0")
    implementation("androidx.appcompat:appcompat:1.7.1")
    implementation("androidx.activity:activity-ktx:1.10.1")
    implementation("com.google.android.material:material:1.12.0")
    implementation("androidx.lifecycle:lifecycle-process:2.10.0")
    testImplementation("junit:junit:4.13.2")
    androidTestImplementation("androidx.test.ext:junit:1.1.4")
    androidTestImplementation("androidx.test.espresso:espresso-core:3.5.0")
}

apply(from = file("tauri.build.gradle.kts"))
